25	constexpr int32_t TOTAL_LENGTH = 8 * 2048;                            // total length of data
26	constexpr int32_t NUM_BLOCKS = 8;                                     // num of block used
27	constexpr int32_t BLOCK_LENGTH = TOTAL_LENGTH / NUM_BLOCKS;           // length computed of each block
28	constexpr int32_t TILE_NUM = 8;                                       // split data into 1 tiles for each block
29	constexpr int32_t BUFFER_NUM = 2;                                     // tensor num for each queue
30	constexpr int32_t TILE_LENGTH = BLOCK_LENGTH / TILE_NUM / BUFFER_NUM; // separate to 2 parts, due to double buffer
31	
32	class KernelAdd {
33	public:
34	    __aicore__ inline KernelAdd() {}
35	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z)
36	    {
37	        xGm.SetGlobalBuffer((__gm__ float*)x + BLOCK_LENGTH * AscendC::GetBlockIdx(), BLOCK_LENGTH);
38	        yGm.SetGlobalBuffer((__gm__ float*)y + BLOCK_LENGTH * AscendC::GetBlockIdx(), BLOCK_LENGTH);
39	        zGm.SetGlobalBuffer((__gm__ float*)z + BLOCK_LENGTH * AscendC::GetBlockIdx(), BLOCK_LENGTH);
40	        pipe.InitBuffer(inQueueX, BUFFER_NUM, TILE_LENGTH * sizeof(float));
41	        pipe.InitBuffer(inQueueY, BUFFER_NUM, TILE_LENGTH * sizeof(float));
42	        pipe.InitBuffer(outQueueZ, BUFFER_NUM, TILE_LENGTH * sizeof(float));
43	    }
44	    __aicore__ inline void Process()
45	    {
46	        int32_t loopCount = TILE_NUM * BUFFER_NUM;
47	        for (int32_t i = 0; i < loopCount; i++) {
48	            CopyIn(i);
49	            Compute(i);
50	            CopyOut(i);
51	        }
52	    }
53	
54	private:
55	    __aicore__ inline void CopyIn(int32_t progress)
56	    {
57	        AscendC::LocalTensor<float> xLocal = inQueueX.AllocTensor<float>();
58	        AscendC::LocalTensor<float> yLocal = inQueueY.AllocTensor<float>();
59	        AscendC::DataCopy(xLocal, xGm[progress * TILE_LENGTH], TILE_LENGTH);
60	        AscendC::DataCopy(yLocal, yGm[progress * TILE_LENGTH], TILE_LENGTH);
61	        inQueueX.EnQue(xLocal);
62	        inQueueY.EnQue(yLocal);
63	    }
64	    __aicore__ inline void Compute(int32_t progress)
65	    {
66	        AscendC::LocalTensor<float> xLocal = inQueueX.DeQue<float>();
67	        AscendC::LocalTensor<float> yLocal = inQueueY.DeQue<float>();
68	        AscendC::LocalTensor<float> zLocal = outQueueZ.AllocTensor<float>();
69	        AscendC::Add(zLocal, xLocal, yLocal, TILE_LENGTH);
70	        outQueueZ.EnQue<float>(zLocal);
71	        inQueueX.FreeTensor(xLocal);
72	        inQueueY.FreeTensor(yLocal);
73	    }
74	    __aicore__ inline void CopyOut(int32_t progress)
75	    {
76	        AscendC::LocalTensor<float> zLocal = outQueueZ.DeQue<float>();
77	        AscendC::DataCopy(zGm[progress * TILE_LENGTH], zLocal, TILE_LENGTH);
78	        outQueueZ.FreeTensor(zLocal);
79	    }
80	
81	private:
82	    AscendC::TPipe pipe;
83	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX, inQueueY;
84	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ;
85	    AscendC::GlobalTensor<float> xGm;
86	    AscendC::GlobalTensor<float> yGm;
87	    AscendC::GlobalTensor<float> zGm;
88	};
