97	std::vector<float> kernel_add(std::vector<float>& x, std::vector<float>& y)
98	{
99	    constexpr uint32_t numBlocks = NUM_BLOCKS;
100	    uint32_t totalLength = x.size();
101	    size_t totalByteSize = totalLength * sizeof(float);
102	    int32_t deviceId = 0;
103	    aclrtStream stream = nullptr;
104	    uint8_t* xHost = reinterpret_cast<uint8_t*>(x.data());
105	    uint8_t* yHost = reinterpret_cast<uint8_t*>(y.data());
106	    uint8_t* zHost = nullptr;
107	    uint8_t* xDevice = nullptr;
108	    uint8_t* yDevice = nullptr;
109	    uint8_t* zDevice = nullptr;
110	
111	    aclInit(nullptr);
112	    aclrtSetDevice(deviceId);
113	    aclrtCreateStream(&stream);
114	
115	    aclrtMallocHost((void**)(&zHost), totalByteSize);
116	    aclrtMalloc((void**)&xDevice, totalByteSize, ACL_MEM_MALLOC_HUGE_FIRST);
117	    aclrtMalloc((void**)&yDevice, totalByteSize, ACL_MEM_MALLOC_HUGE_FIRST);
118	    aclrtMalloc((void**)&zDevice, totalByteSize, ACL_MEM_MALLOC_HUGE_FIRST);
119	
120	    aclrtMemcpy(xDevice, totalByteSize, xHost, totalByteSize, ACL_MEMCPY_HOST_TO_DEVICE);
121	    aclrtMemcpy(yDevice, totalByteSize, yHost, totalByteSize, ACL_MEMCPY_HOST_TO_DEVICE);
122	
123	    add_custom<<<numBlocks, nullptr, stream>>>(xDevice, yDevice, zDevice);
124	    aclrtSynchronizeStream(stream);
125	
126	    aclrtMemcpy(zHost, totalByteSize, zDevice, totalByteSize, ACL_MEMCPY_DEVICE_TO_HOST);
127	    std::vector<float> z((float*)zHost, (float*)(zHost + totalByteSize));
128	
129	    aclrtFree(xDevice);
130	    aclrtFree(yDevice);
131	    aclrtFree(zDevice);
132	    aclrtFreeHost(zHost);
133	
134	    aclrtDestroyStream(stream);
135	    aclrtResetDevice(deviceId);
136	    aclFinalize();
137	
138	    return z;
139	}
